public static class QueryBuilder
{
    public static bool QueryBuilder(string text, string query)
    {
        return text.Contains(query.ToLower());
    }
}

solutionCode:
public static class QueryBuilder
{
    public static bool QueryBuilder(string text, string query)
    {
        return text.ToLower().Contains(query.ToLower());
    }
}
